#!/usr/bin/env python3
"""
time_adjuster.py

Reads an attendance CSV file, subtracts 4 hours from every value in the
` Clock-out` column, and saves the result as an Excel file at
/workspace/adjusted-april-attendance.xlsx.

Usage:
    python time_adjuster.py <input_csv_path>
"""

import sys
from datetime import datetime, timedelta

import pandas as pd


OUTPUT_PATH = "/workspace/adjusted-april-attendance.xlsx"
CLOCK_OUT_COL = " Clock-out"
HOURS_TO_SUBTRACT = 4


def subtract_hours(value, hours=HOURS_TO_SUBTRACT):
    """Subtract `hours` hours from a time value.

    Handles pandas/NumPy NaN, datetime/Timestamp objects, time objects,
    and string representations of times like 'HH:MM' or 'HH:MM:SS'.
    """
    # Handle missing values
    if value is None:
        return value
    try:
        if pd.isna(value):
            return value
    except (TypeError, ValueError):
        pass

    # If it's already a datetime/Timestamp, subtract directly
    if isinstance(value, (pd.Timestamp, datetime)):
        return value - timedelta(hours=hours)

    # If it's a time object, combine with a dummy date, subtract, return time
    import datetime as _dt
    if isinstance(value, _dt.time):
        dummy = datetime.combine(datetime(2000, 1, 1), value)
        return (dummy - timedelta(hours=hours)).time()

    # Otherwise treat as string
    s = str(value).strip()
    if not s:
        return value

    # Try common time/datetime formats
    formats = [
        "%H:%M:%S",
        "%H:%M",
        "%Y-%m-%d %H:%M:%S",
        "%Y-%m-%d %H:%M",
        "%m/%d/%Y %H:%M:%S",
        "%m/%d/%Y %H:%M",
    ]
    for fmt in formats:
        try:
            parsed = datetime.strptime(s, fmt)
            adjusted = parsed - timedelta(hours=hours)
            # Return in the same format the input used
            return adjusted.strftime(fmt)
        except ValueError:
            continue

    # Fallback: try pandas' flexible parser
    try:
        parsed = pd.to_datetime(s)
        return parsed - timedelta(hours=hours)
    except (ValueError, TypeError):
        # If we cannot parse, return the original value unchanged
        return value


def main():
    if len(sys.argv) < 2:
        print("Usage: python time_adjuster.py <input_csv_path>", file=sys.stderr)
        sys.exit(1)

    input_path = sys.argv[1]

    # Read the CSV preserving original column names (including leading space)
    df = pd.read_csv(input_path)

    if CLOCK_OUT_COL not in df.columns:
        # Try without leading space as a fallback
        alt = CLOCK_OUT_COL.strip()
        if alt in df.columns:
            col_to_use = alt
        else:
            print(
                f"Error: Column '{CLOCK_OUT_COL}' not found in {input_path}. "
                f"Available columns: {list(df.columns)}",
                file=sys.stderr,
            )
            sys.exit(2)
    else:
        col_to_use = CLOCK_OUT_COL

    df[col_to_use] = df[col_to_use].apply(subtract_hours)

    df.to_excel(OUTPUT_PATH, index=False)
    print(f"Wrote adjusted file to {OUTPUT_PATH}")


if __name__ == "__main__":
    main()
